import { tv, type VariantProps } from "@/lib/beton/tv";

export const skeleton = tv({
  base: ["block bg-surface", "border-3 border-border", "motion-safe:animate-pulse-stepped"],
  variants: {
    shape: {
      line: "h-4 w-full",
      title: "h-8 w-2/3",
      block: "h-32 w-full",
      avatar: "size-11 rounded-md",
      button: "h-12 w-32",
    },
  },
  defaultVariants: {
    shape: "line",
  },
});

export type SkeletonVariants = VariantProps<typeof skeleton>;

import { skeleton, type SkeletonVariants } from "@/lib/beton/recipes/skeleton.recipe";
import type { ComponentProps } from "react";
import { renderElement, type RenderProp } from "@/lib/beton/render-element";

export interface SkeletonProps extends ComponentProps<"span">, SkeletonVariants {
  render?: RenderProp;
}

/**
 * A placeholder for content that has not arrived. Hidden from screen readers:
 * put the loading state in a live region or on the control that started it.
 */
export function Skeleton({ shape = "line", className, render, ...props }: SkeletonProps) {
  return renderElement(
    "span",
    {
      ...props,
      "aria-hidden": "true",
      className: skeleton({ shape, class: className }),
    },
    render,
  );
}
